                else if (char == 0x09) _unsafeWriteBytesOffset(output, outputLength++, "t");
                else if (char == 0x0a) _unsafeWriteBytesOffset(output, outputLength++, "n");
                else if (char == 0x0c) _unsafeWriteBytesOffset(output, outputLength++, "f");
                else if (char == 0x0d) _unsafeWriteBytesOffset(output, outputLength++, "r");
                else if (char == 0x5c) _unsafeWriteBytesOffset(output, outputLength++, "\\");
                else if (char == 0x22) {
                    // solhint-disable-next-line quotes
                    _unsafeWriteBytesOffset(output, outputLength++, '"');
                } else {
                    // U+0000 to U+001F without short form: output \u00XX
                    _unsafeWriteBytesOffset(output, outputLength++, "u");
                    _unsafeWriteBytesOffset(output, outputLength++, "0");
                    _unsafeWriteBytesOffset(output, outputLength++, "0");
                    _unsafeWriteBytesOffset(output, outputLength++, HEX_DIGITS[char >> 4]);
                    _unsafeWriteBytesOffset(output, outputLength++, HEX_DIGITS[char & 0x0f]);
                }
            } else {
                _unsafeWriteBytesOffset(output, outputLength++, bytes1(char));
            }
        }
        // write the actual length and reserve memory
        assembly ("memory-safe") {
            mstore(output, outputLength)
            mstore(0x40, add(output, add(outputLength, 0x20)))
        }

        return string(output);
    }

    /**
     * @dev Reads a bytes32 from a bytes array without bounds checking.
     *
     * NOTE: making this function internal would mean it could be used with memory unsafe offset, and marking the
     * assembly block as such would prevent some optimizations.
     */
    function _unsafeReadBytesOffset(bytes memory buffer, uint256 offset) private pure returns (bytes32 value) {
        // This is not memory safe in the general case, but all calls to this private function are within bounds.
        assembly ("memory-safe") {
            value := mload(add(add(buffer, 0x20), offset))
        }
    }

    /**
     * @dev Write a bytes1 to a bytes array without bounds checking.
     *
     * NOTE: making this function internal would mean it could be used with memory unsafe offset, and marking the
     * assembly block as such would prevent some optimizations.
     */
    function _unsafeWriteBytesOffset(bytes memory buffer, uint256 offset, bytes1 value) private pure {
        // This is not memory safe in the general case, but all calls to this private function are within bounds.
        assembly ("memory-safe") {
            mstore8(add(add(buffer, 0x20), offset), shr(248, value))
        }
    }
}

contracts/BondManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title CATT Protocol Real Yield Bonds
 * @notice Fixed-term $CATT bond vault implementing PRD Section 3.3, "Real Yield
 *         Bonds": users lock CATT principal for 30, 90 or 180 days and earn
 *         yield funded exclusively by B2B sponsor deposits of a stablecoin.
 *
 * @dev THE CENTRAL ECONOMIC CLAIM (PRD 3.3): the yield a bondholder receives is
 *      money that a B2B sponsor paid in for educational article distribution.
 *      Bond yield is NEVER minted, never printed and never funded by further
 *      CATT issuance. This contract cannot inflate $CATT by construction: it
 *      holds two immutable ERC20 references and the only CATT it ever moves is
 *      principal that a user voluntarily locked and will get back at maturity.
 *      A sponsor who stops depositing simply stops the yield; the debt owed to
 *      bondholders is capped by the stablecoin actually held here, and the
 *      contract pays out only what it holds.
 *
 * @dev Yield accounting — checkpointed reward-per-point:
 *      - A bond's `points = principal * tierWeight`. There is deliberately NO
 *        extra scaling applied to the principal: CATT is already an
 *        18-decimal base unit and the tier weights are the small integers
 *        1..3, so the point value is simply a 1x/2x/3x multiplier.
 *      - `accYieldPerPoint` is a 1e18-scaled cumulative accumulator. A sponsor
 *        deposit of `amount` adds `(amount * ACC_PRECISION) / totalPoints` to it.
 *      - EVERY bond stores `accSnapshot`, the value of `accYieldPerPoint` AT
 *        THE MOMENT OF ITS CREATION, and its claimable yield is always
 *        `points * (accYieldPerPoint - accSnapshot) / ACC_PRECISION`.
 *
 *      This checkpoint is THE single most important correctness property in the
 *      contract, so it is stated in full:
 *        (1) A bond created BEFORE a deposit earns from that deposit, because
 *            its snapshot is strictly less than the post-deposit accumulator.
 *        (2) A bond created AFTER a deposit can NEVER earn retroactively from
 *            it, because the snapshot it stores is the accumulator that already
 *            includes the deposit's increment. Joining late therefore dilutes
 *            nothing retroactively, and there is no "front-run the accumulator"
 *            exploit: the accumulator only moves forward and a late joiner is
 *            shielded from all of it.
 *        (3) The snapshot is read BEFORE the bond's points are added to
 *            `totalPoints` and before any other state write in `buyBond`, so
 *            the bond is measured against the pre-existing accumulator even
 *            though it starts earning on new deposits immediately afterwards.
 *        (4) A partial `claimYield` deliberately does NOT move the snapshot, so
 *            a bond keeps earning on the same points after being paid; the
 *            checkpoint tracks "when this bond joined", never "when it was last
 *            paid". What stops a repeated claim from re-paying the same accrual
 *            is the separate `accruedYield` deduction inside `pendingYield`:
 *            the snapshot stays put, the already-paid amount is subtracted, and
 *            so a bond that has been collected in full reads 0 and can never be
 *            paid twice.
 *
 * @dev Point accounting:
 *      - `totalPoints` counts OPEN bonds only: it is incremented in `buyBond`
 *        and decremented by the bond's own `points` in `redeem`. Because the
 *        increment and the decrement are both derived from the stored bond
 *        record, `totalPoints` cannot drift from the sum of open-bond points.
 *      - `depositYield` reverts `NoActiveBonds` when `totalPoints == 0`. There
 *        is deliberately NO "idle pool": at least one bond must exist before the
 *        first sponsor deposit can be accepted, because with no points a
 *        deposit has nobody to allocate to and any accumulator bump would be
 *        permanently unattributable. Sponsors should create accounting for
 *        their campaign window up front.
 *      - Integer truncation is accounted for, not hidden. With
 *        `increment = amount * ACC_PRECISION / totalPoints` and
 *        `distributed = increment * totalPoints / ACC_PRECISION`, the residue
 *        `amount - distributed` is added to `unallocatedYield` and stays held by
 *        this contract. That is at most `totalPoints - 1` base units of the
 *        yield token per deposit, i.e. pure rounding dust. It is intentionally
 *        NOT redistributable: pushing it out would require a second accounting
 *        pass that credits yield to bonds that were already settled, which
 *        would retroactively re-allocate value across the term and break the
 *        checkpoint invariant in (1)-(4) above. The dust is instead reported on
 *        chain and the full solvency invariant
 *          `yieldToken.balanceOf(this) == unallocatedYield
 *                                 + yield still claimable by open bonds`
 *        therefore holds at all times, with the companion lifetime identity
 *          `sum(sponsor deposits) == unallocatedYield
 *                                 + sum(yield still claimable)
 *                                 + sum(yield already paid out)`
 *        holding as well, so no deposited unit is ever lost, created or spent
 *        twice. Note the CATT balance is a separate, exactly tracked quantity:
 *        it always equals the sum of the principals of the open bonds.
 *      - Overflow safety, stated explicitly: `amount * ACC_PRECISION` is safe
 *        because real stablecoin supplies lie between 1e6 and 1e15 base units,
 *        which is more than two hundred orders of magnitude below
 *        `2^256 / 1e18 (~1.16e59)`. `points` is bounded by
 *        `3 * CATT.MAX_SUPPLY` = 3e8 * 1e18 = 3e26, and the per-bond product
 *        `points * (accYieldPerPoint - accSnapshot)` is bounded by the total
 *        distributed yield scaled by 1e18, so the whole reward-per-point
 *        surface stays far inside uint256 even in the worst case.
 *
 * @dev Security posture (PRD Section 5, Rule 1):
 *      - Every state-changing function is `nonReentrant`. `buyBond` and
 *        `depositYield` pull tokens before writing state (pull-first, justified
 *        in the body); `claimYield` and `redeem` write state before paying
 *        out (checks-effects-interactions), so a non-standard yield token
 *        cannot observe an unsettled position.
 *      - All timing uses `block.timestamp` only. No block number is read
 *        anywhere in this contract. Maturity is a strict `>=` comparison
 *        against the bond's stored `maturesAt`.
 *      - `SafeERC20` is used for BOTH tokens, so a USDT-style principal or
 *        yield token that returns no boolean on `transfer` is still handled.
 *
 * @dev Deliberate non-goals, so that auditors do not look for them:
 *      - NO EARLY EXIT. Principal is non-cancellable for the whole term. There
 *        is no penalty, no forfeit, no partial unwind and no emergency exit.
 *        That is the point: an uncancellable fixed-term commitment is what
 *        makes the bond credible to a sponsor who is underwriting the yield
 *        with real money. `withdrawPrincipal` exists only to make that lock
 *        explicit, self-documenting and unit-testable rather than merely absent.
 *      - NO OWNER RESCUE OR SWEEP. The owner can only ADD yield; it can never
 *        move sponsor funds out. Funds are unrecoverable if bonds never mature,
 *        which is the deliberate cost of making the pool un-rugable.
 *      - No pause, no upgradeability, no off-chain signature verification, no
 *        backend/frontend code, no bond transferability or secondary market, no
 *        fees on bond purchase, and no native token handling: this contract
 *        holds no MATIC and has no `receive`/`fallback`, so the protocol stays
 *        correct if Polygon becomes an EVM-only chain.
 *
 * @dev No private keys, API keys or deployment secrets appear in this source
 *      file; those are supplied by the deployer's environment (PRD Rule 2).
 */
contract BondManager is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    /// @notice Number of bond terms offered by the protocol.
    /// @dev Tier INDICES are 1-based, so the valid range is 1..TIER_COUNT and
    ///      index 0 is never a valid tier.
    uint8 public constant TIER_COUNT = 3;

    /// @notice Fixed-point scale applied to the reward-per-point accumulator.
    /// @dev 1e18 keeps the per-point yield meaningful for 6-decimal stablecoins
    ///      while staying far away from the uint256 boundary.
    uint256 public constant ACC_PRECISION = 1e18;

    /// @notice Term of tier 1: 30 days.
    uint256 public constant TIER_1_DURATION = 30 days;

    /// @notice Term of tier 2: 90 days.
    uint256 public constant TIER_2_DURATION = 90 days;

    /// @notice Term of tier 3: 180 days.
    uint256 public constant TIER_3_DURATION = 180 days;

    /// @notice Yield weight of tier 1 (1x).
    uint256 public constant TIER_1_WEIGHT = 1;

    /// @notice Yield weight of tier 2 (2x).
    uint256 public constant TIER_2_WEIGHT = 2;

    /// @notice Yield weight of tier 3 (3x).
    uint256 public constant TIER_3_WEIGHT = 3;

    /// @notice Immutable reference to the CATT token locked as bond principal.
    IERC20 public immutable principalToken;

    /// @notice Immutable reference to the stablecoin sponsors pay yield in.
    IERC20 public immutable yieldToken;

    /// @notice Sum of the points of every currently OPEN bond.
    /// @dev Incremented in `buyBond` and decremented in `redeem`. Bounces to
    ///      0 only when no bond is open, which is the only window in which
    ///      `depositYield` is rejected.
    uint256 public totalPoints;

    /// @notice Cumulative yield owed per point, scaled by `ACC_PRECISION`.
    /// @dev Monotonically increasing. Only ever written by `depositYield`, so
    ///      the value read by a bond is a pure function of the deposits that
    ///      happened while it was open.
    uint256 public accYieldPerPoint;

    /// @notice Rounding residue held by this contract from deposit truncation.
    /// @dev Reported, never redistributed. See the header for the full
    ///      solvency invariant this balance supports.
    uint256 public unallocatedYield;

    /// @notice Count of bonds ever created; also the NEXT bond id (1-based).
    /// @dev Ids are 1-based, so id 0 is never valid and `totalBondsCreated`
    ///      equals the number of bonds that exist.
    uint256 public totalBondsCreated;

    /// @notice A single locked bond position.
    /// @param holder Account that locked the principal; the only party that can
    ///        claim or redeem this bond.
    /// @param principal CATT locked by the bond, in 18-decimal base units.
    /// @param tier 1-based tier index, 1..3.
    /// @param createdAt `block.timestamp` at which the bond was opened.
    /// @param maturesAt `block.timestamp` from which the bond is redeemable.
    /// @param points `principal * tierWeight`; its share of every deposit.
    /// @param accSnapshot Value of `accYieldPerPoint` at creation time. This
    ///        is the checkpoint that makes retroactive yield impossible.
    /// @param accruedYield Yield already paid out to the holder by
    ///        `claimYield` and by `redeem`, in yield-token base units.
    /// @param closed True once the bond has been redeemed.
    struct Bond {
        address holder;
        uint256 principal;
        uint8 tier;
        uint40 createdAt;
        uint40 maturesAt;
        uint256 points;
        uint256 accSnapshot;
        uint256 accruedYield;
        bool closed;
    }

    /// @notice Bond records keyed by 1-based bond id.
    /// @dev Deliberately `private`: a public mapping of a struct would emit an
    ///      auto-generated getter whose return tuple is unlabelled and easy to
    ///      mis-order in an integration. `bondInfo` and `bondAccSnapshot` are
    ///      the single, named read path.
    mapping(uint256 => Bond) private _bonds;

    /// @notice Emitted when a new bond is opened.
    /// @param bondId 1-based id of the new bond.
    /// @param holder Account that locked the principal.
    /// @param principal CATT locked, in 18-decimal base units.
    /// @param tier 1-based tier index.
    /// @param maturesAt Timestamp from which the bond can be redeemed.
    /// @param points Points the bond contributes to `totalPoints`.
    event BondCreated(
        uint256 indexed bondId,
        address indexed holder,
        uint256 principal,
        uint8 tier,
        uint40 maturesAt,
        uint256 points
    );

    /// @notice Emitted when a sponsor funds the yield pool.
    /// @param depositor Sponsor account that supplied the stablecoin.
    /// @param amount Stablecoin pulled in, in yield-token base units.
    /// @param newAccYieldPerPoint Accumulator after the deposit was applied.
    event YieldDeposited(address indexed depositor, uint256 amount, uint256 newAccYieldPerPoint);

    /// @notice Emitted when a bondholder pulls part of its yield.
    /// @param bondId Bond that was paid.
    /// @param holder Recipient of the yield.
    /// @param amount Yield transferred, in yield-token base units.
    event YieldClaimed(uint256 indexed bondId, address indexed holder, uint256 amount);

    /// @notice Emitted when a matured bond is closed and fully paid out.
    /// @param bondId Bond that was closed.
    /// @param holder Recipient of both legs of the payout.
    /// @param principal CATT returned, in 18-decimal base units.
    /// @param yield Final yield paid alongside the principal.
    event BondRedeemed(
        uint256 indexed bondId,
        address indexed holder,
        uint256 principal,
        uint256 yield
    );

    /// @notice Thrown when a token address is the zero address.
    /// @dev The zero address is never a valid token: bonding against it would
    ///      permanently lock the caller's principal with no way out.
    error ZeroAddress();

    /// @notice Thrown when a supplied amount is zero.
    error ZeroAmount();

    /// @notice Thrown when a tier index is outside 1..TIER_COUNT.
    /// @dev Tier indices are 1-based, so 0 and 4..255 are all rejected.
    /// @param tier The rejected index.
    error InvalidTier(uint8 tier);

    /// @notice Thrown when a bond id has never been created.
    /// @dev Ids are 1-based, so id 0 is always rejected as well.
    /// @param bondId The unknown id.
    error InvalidBondId(uint256 bondId);

    /// @notice Thrown when the bond has already been redeemed.
    /// @param bondId The closed bond.
    error BondClosed(uint256 bondId);

    /// @notice Thrown by `withdrawPrincipal` for any live bond.
    /// @dev The arguments make the lock self-describing on-chain and let a
    ///      frontend or test compute the remaining wait without off-chain help.
    /// @param bondId The bond that cannot be exited.
    /// @param maturesAt Timestamp from which redemption becomes possible.
    /// @param currentTime `block.timestamp` at the time of the attempt.
    error BondLockedUntilMaturity(uint256 bondId, uint256 maturesAt, uint256 currentTime);

    /// @notice Thrown when a bond is redeemed before its maturity.
    /// @param bondId The immature bond.
    /// @param maturesAt Timestamp from which redemption becomes possible.
    /// @param currentTime `block.timestamp` at the time of the attempt.
    error BondNotMatured(uint256 bondId, uint256 maturesAt, uint256 currentTime);

    /// @notice Thrown when a claim or redemption resolves to zero yield.
    /// @dev Almost always a claim made between two deposits.
    /// @param bondId The bond with nothing to pay.
    error NothingToClaim(uint256 bondId);

    /// @notice Thrown when a sponsor deposits while no bond is open.
    /// @dev With `totalPoints == 0` there is no one to allocate the deposit
    ///      to, and an unattributed accumulator bump would be permanently
    ///      undistributable.
    error NoActiveBonds();

    /// @notice Thrown when the yield pool cannot cover an obligation.
    /// @dev Should be unreachable: the pool is funded before the accumulator
    ///      moves, so the sum of all claims can never exceed the balance. It is
    ///      kept as a hard, explicit failure rather than a silent revert of a
    ///      bare transfer.
    /// @param required Yield the bond is owed, in yield-token base units.
    /// @param available Yield actually held by this contract.
    error InsufficientYieldPool(uint256 required, uint256 available);

    /// @notice Thrown when a non-holder tries to claim a bond's yield.
    /// @param bondId The bond whose yield was targeted.
    /// @param caller The address that attempted the claim.
    error NotBondHolder(uint256 bondId, address caller);

    /**
     * @notice Deploys the bond manager against the principal and yield tokens.
     * @dev Both references are `immutable`: the principal denomination and the
     *      yield denomination define what every existing bond IS, so allowing
     *      either to change would silently reinterpret all outstanding bonds.
     *      Reverts with `ZeroAddress` if either is unset.
     *
     *      The two MUST be distinct tokens, and the constructor does not police
     *      it: the deploy script is responsible for pairing CATT with a real
     *      stablecoin. Passing the same address twice would make principal and
     *      yield indistinguishable in the vault's balance and would let a
     *      yield claim pay out out of other users' locked principal.
     * @param principalToken_ Address of the CATT ERC20 token to be bonded.
     * @param yieldToken_ Address of the sponsor-funded stablecoin.
     */
    constructor(address principalToken_, address yieldToken_) Ownable(msg.sender) {
        if (principalToken_ == address(0)) revert ZeroAddress();
        if (yieldToken_ == address(0)) revert ZeroAddress();

        principalToken = IERC20(principalToken_);
        yieldToken = IERC20(yieldToken_);
    }

    /**
     * @notice Length of a bond term, in seconds.
     * @dev Tiers are 1-BASED: tier 1 is 30 days, tier 2 is 90 days, tier 3 is
     *      180 days (PRD 3.3, "Bonds (30/90/180 days)"). Every other index,
     *      including 0, is not a valid tier and reverts with `InvalidTier`.
     *
     *      The tiers are exposed as validated views rather than as a loose
     *      mapping, precisely so that an out-of-range tier cannot silently read
     *      as "zero duration" or "zero weight" and produce a bond that is
     *      instantly redeemable or worth nothing.
     *      (The return value is named `duration` rather than `seconds`
     *      because `seconds` is a reserved type alias in Solidity and cannot
     *      be used as an identifier.)
     * @param tier 1-based tier index, 1..3.
     * @return duration Term length of the tier.
     */
    function tierDuration(uint8 tier) public pure returns (uint256 duration) {
        if (tier == 1) return TIER_1_DURATION;
        if (tier == 2) return TIER_2_DURATION;
        if (tier == 3) return TIER_3_DURATION;
        revert InvalidTier(tier);
    }

    /**
     * @notice Yield weight of a tier, the multiplier applied to the principal
     *         to obtain the bond's points.
     * @dev Tiers are 1-BASED: tier 1 weighs 1x, tier 2 weighs 2x, tier 3 weighs
     *      3x, so a longer commitment earns proportionally more of the same
     *      sponsor-funded pool. Every other index, including 0, reverts with
     *      `InvalidTier`.
     * @param tier 1-based tier index, 1..3.
     * @return weight Multiplier applied to the bonded principal.
     */
    function tierWeight(uint8 tier) public pure returns (uint256 weight) {
        if (tier == 1) return TIER_1_WEIGHT;
        if (tier == 2) return TIER_2_WEIGHT;
        if (tier == 3) return TIER_3_WEIGHT;
        revert InvalidTier(tier);
    }

    /**
     * @notice Convenience view returning both parameters of a tier.
     * @dev Thin wrapper over `tierDuration` and `tierWeight` so a frontend
     *      can render a tier table with a single call; reverts `InvalidTier`
     *      identically.
     * @param tier 1-based tier index, 1..3.
     * @return duration Term length of the tier, in seconds.
     * @return weight Yield weight of the tier.
     */
    function tierInfo(uint8 tier) external pure returns (uint256 duration, uint256 weight) {
        duration = tierDuration(tier);
        weight = tierWeight(tier);
    }

    /**
     * @notice Full record of a bond.
     * @dev The ONLY read path for bond data; `_bonds` is private precisely so
     *      that this labelled tuple stays the stable integration surface.
     *      Reverts with `InvalidBondId` for an id that was never created.
     * @param bondId 1-based id of the bond.
     * @return holder Account that locked the principal.
     * @return principal CATT locked, in 18-decimal base units.
     * @return tier 1-based tier index.
     * @return createdAt Timestamp the bond was opened.
     * @return maturesAt Timestamp the bond becomes redeemable.
     * @return points Points the bond contributes while open.
     * @return accruedYield Yield already paid out to the holder.
     * @return closed True once the bond has been redeemed.
     */
    function bondInfo(uint256 bondId)
        external
        view
        returns (
            address holder,
            uint256 principal,
            uint8 tier,
            uint256 createdAt,
            uint256 maturesAt,
            uint256 points,
            uint256 accruedYield,
            bool closed
        )
    {
        Bond storage bond = _requireBond(bondId);
        return (
            bond.holder,
            bond.principal,
            bond.tier,
            uint256(bond.createdAt),
            uint256(bond.maturesAt),
            bond.points,
            bond.accruedYield,
            bond.closed
        );
    }

    /**
     * @notice Checkpoint a bond was opened against: the value of
     *         `accYieldPerPoint` at its creation.
     * @dev Exposed separately so tests and indexers can assert the checkpoint
     *      invariant directly (a bond's yield is always measured from this
     *      value), rather than having to infer it. Reverts with
     *      `InvalidBondId` for an id that was never created.
     * @param bondId 1-based id of the bond.
     * @return snapshot The 1e18-scaled accumulator captured at creation.
     */
    function bondAccSnapshot(uint256 bondId) external view returns (uint256 snapshot) {
        snapshot = _requireBond(bondId).accSnapshot;
    }

    /**
     * @notice Yield a bond has earned but not yet collected.
     *
     * @dev Exactly `points * (accYieldPerPoint - accSnapshot) / ACC_PRECISION`
     *      for an open bond, MINUS whatever has already been paid out to the
     *      holder (`accruedYield`). Returns 0 — rather than reverting — for an
     *      id that was never created and for a bond that has already been
     *      redeemed, because this is a UI-facing estimate that must never throw;
     *      the state-changing callers use the reverting `_requireBond` helper
     *      instead.
     *
     *      The subtraction of `accruedYield` is load-bearing, not cosmetic. The
     *      gross figure above is the bond's LIFETIME accrual and is monotonically
     *      non-decreasing; if it were returned as the claimable amount then every
     *      call to `claimYield` would pay the bond's whole lifetime accrual again,
     *      so a holder could call it in a loop and drain the pool — including
     *      yield owed to other bondholders. The `InsufficientYieldPool` guard
     *      would then be the only thing stopping a griefing loop, and it would
     *      revert a claim the holder was legitimately entitled to. Deducting what
     *      has already been paid is what makes `claimYield` a COLLECTION rather
     *      than a re-declaration: a bond that has been paid in full reads 0 here
     *      and reverts `NothingToClaim`, and every later deposit is paid exactly
     *      once.
     *
     *      Note the deliberate split of responsibilities: the DEDUCTION lives
     *      here, in the view, and `accSnapshot` is NOT moved by a claim. The
     *      snapshot remains a pure "when did this bond join" checkpoint, so the
     *      bond keeps earning on exactly the same points after being paid, and
     *      the lifetime accrual of an already-settled bond is never re-priced.
     * @param bondId 1-based id of the bond.
     * @return amount Claimable yield, in yield-token base units.
     */
    function pendingYield(uint256 bondId) public view returns (uint256 amount) {
        Bond storage bond = _bonds[bondId];
        if (bond.holder == address(0)) return 0;
        if (bond.closed) return 0;
        uint256 lifetimeAccrual = (bond.points * (accYieldPerPoint - bond.accSnapshot)) / ACC_PRECISION;
        // The clamped subtraction also covers the theoretical case of a bond
        // whose stored `accruedYield` exceeds its recomputed lifetime accrual,
        // which rounding could in principle produce; it must never underflow
        // into an enormous claim.
        amount = lifetimeAccrual > bond.accruedYield ? lifetimeAccrual - bond.accruedYield : 0;
    }

    /**
     * @notice True once the bond's maturity timestamp has been reached.
     * @dev Same strict `block.timestamp` comparison as `redeem`, exposed so a
     *      frontend can enable the redeem button without simulating the call.
     *      An unknown id is not matured.
     * @param bondId 1-based id of the bond.
     * @return matured Whether the bond may be redeemed now.
     */
    function isMatured(uint256 bondId) external view returns (bool matured) {
        Bond storage bond = _bonds[bondId];
        if (bond.holder == address(0)) return false;
        matured = block.timestamp >= uint256(bond.maturesAt);
    }

    /**
     * @notice Locks `amount` CATT in a new bond of `tier` and returns its id.
     *
     * @dev No fee is charged on purchase, and the full `amount` becomes
     *      principal, refundable at maturity.
     *
     *      Ordering — the external `safeTransferFrom` runs FIRST, before any
     *      bookkeeping write, exactly as in `StakingManager`. Pulling the
     *      tokens first means a transfer that is not honoured (a fee-on-transfer
     *      token, a block-listed holder, or any future non-standard behaviour)
     *      reverts the whole transaction, so a bond can never be recorded for
     *      CATT this contract did not receive. Inverting the order is safe
     *      here for the same reason it is safe there: `nonReentrant` already
     *      closes the re-entrancy question, so no re-entrant caller can observe
     *      the intermediate state that the inversion would create.
     *
     *      The accumulator checkpoint is then read BEFORE the bond's points
     *      join `totalPoints` and before any state write, so the new bond is
     *      measured against the accumulator that existed when the user arrived
     *      and can never be credited with yield deposited before it existed.
     *
     *      Reverts with `ZeroAmount` for a zero amount, `InvalidTier` for a
     *      tier outside 1..3, and the standard ERC20 allowance/balance errors
     *      if the caller has not approved this contract.
     * @param amount CATT to lock, in 18-decimal base units. Must be > 0.
     * @param tier 1-based tier index: 1 (30d, 1x), 2 (90d, 2x), 3 (180d, 3x).
     * @return bondId The 1-based id of the newly created bond.
     */
    function buyBond(uint256 amount, uint8 tier) external nonReentrant returns (uint256 bondId) {
        if (amount == 0) revert ZeroAmount();

        uint256 weight = tierWeight(tier);
        uint256 duration = tierDuration(tier);
        uint256 points = amount * weight;

        // Interaction first, effects after: see the ordering rationale above.
        principalToken.safeTransferFrom(msg.sender, address(this), amount);

        // CRITICAL: checkpoint the accumulator BEFORE the points join
        // `totalPoints`, so this bond cannot be credited with any deposit
        // made before it existed.
        uint256 snapshot = accYieldPerPoint;
        uint40 createdAt = uint40(block.timestamp);
        uint40 maturesAt = uint40(block.timestamp + duration);

        bondId = totalBondsCreated + 1;
        totalBondsCreated = bondId;

        _bonds[bondId] = Bond({
            holder: msg.sender,
            principal: amount,
            tier: tier,
            createdAt: createdAt,
            maturesAt: maturesAt,
            points: points,
            accSnapshot: snapshot,
            accruedYield: 0,
            closed: false
        });

        totalPoints += points;

        emit BondCreated(bondId, msg.sender, amount, tier, maturesAt, points);
    }

    /**
     * @notice ALWAYS REVERTS: the explicit, testable statement that bond
     *         principal cannot be withdrawn before maturity.
     * @dev There is deliberately NO early exit, no penalty path and no forfeit
     *      path for a live bond. Principal is non-cancellable for the entire
     *      term, and that rigidity is the feature: a sponsor underwrites the
     *      yield with real money and needs a credible, non-cancellable
     *      commitment underneath it. A bond that could be unwound on demand
     *      would be a warehouse receipt that its holder can cash out whenever
     *      rates move, which is precisely the risk the sponsor is being asked
     *      to take.
     *
     *      The function exists anyway, and always reverts, for three reasons:
     *      (1) the lock is then an explicit, on-chain, self-documenting
     *          statement rather than merely an absence of a function;
     *      (2) `BondLockedUntilMaturity` carries `maturesAt` and
     *          `block.timestamp`, so a caller learns exactly how long it must
     *          wait without an off-chain call;
     *      (3) PRD Rule 4 requires the lock to be unit-testable — and a
     *          behaviour that is only a missing function cannot be asserted.
     *
     *      A bond that has already been redeemed reverts with `BondClosed`
     *      instead, because there is no principal left in it to be locked.
     * @param bondId 1-based id of the bond to attempt to exit.
     */
    function withdrawPrincipal(uint256 bondId) external nonReentrant {
        Bond storage bond = _requireBond(bondId);
        if (bond.closed) revert BondClosed(bondId);

        revert BondLockedUntilMaturity(bondId, uint256(bond.maturesAt), block.timestamp);
    }

    /**
     * @notice Funds the yield pool with `amount` of the sponsor stablecoin and
     *         spreads it across every currently open bond.
     * @dev Owner-gated: the owner is the B2B sponsor treasury that has collected
     *      revenue from educational article distribution. The owner can ONLY
     *      add funds here; there is deliberately no rescue, sweep or refund
     *      function, so the pool cannot be rugged by the very account that
     *      funds it. That is bought at the price of funds being permanently
     *      unrecoverable if bonds never reach maturity — a deliberate,
     *      documented trade-off in favour of bondholder safety.
     *
     *      Distribution: the accumulator gains `(amount * ACC_PRECISION) /
     *      totalPoints`, and the truncation residue `amount - distributed` is
     *      added to `unallocatedYield` so the contract's balance is fully
     *      accountable at all times. The residue is intentionally NOT
     *      redistributed to already-settled bonds.
     *
     *      Ordering: the pull happens before the accumulator moves, so the
     *      yield is in hand before any bond can claim it.
     *
     *      Reverts with `ZeroAmount` for a zero amount, `NoActiveBonds` when
     *      `totalPoints == 0` (there is no idle pool by design), and the
     *      standard ERC20 allowance/balance errors if the owner has not
     *      approved this contract.
     * @param amount Stablecoin to add, in yield-token base units. Must be > 0.
     */
    function depositYield(uint256 amount) external onlyOwner nonReentrant {
        if (amount == 0) revert ZeroAmount();
        if (totalPoints == 0) revert NoActiveBonds();

        yieldToken.safeTransferFrom(msg.sender, address(this), amount);

        uint256 increment = (amount * ACC_PRECISION) / totalPoints;
        uint256 distributed = (increment * totalPoints) / ACC_PRECISION;

        accYieldPerPoint += increment;
        unallocatedYield += (amount - distributed);

        emit YieldDeposited(msg.sender, amount, accYieldPerPoint);
    }

    /**
     * @notice Pays the caller the yield its open bond has earned so far.
     * @dev Only the bond's own holder may call this; a third party reverts
     *      with `NotBondHolder` and cannot redirect a payout. Payout always
     *      goes to `bond.holder`, never to `msg.sender`'s choice of address.
     *
     *      A claim is purely a COLLECTION, not an event that changes the bond's
     *      economics: it does not extend the term, it does not move
     *      `accSnapshot`, and it does not change `points`. The bond keeps
     *      earning on exactly the same points until it is redeemed, so a user
     *      may claim daily, once, or never before maturity and end up with the
     *      same total.
     *
     *      What makes it a collection and not a re-declaration is the
     *      `accruedYield` deduction inside `pendingYield`: `amount` is the
     *      bond's lifetime accrual minus everything already paid to the holder,
     *      so the same accrual can never be transferred twice, no matter how
     *      often this is called. A fully-collected bond reads 0 and reverts
     *      `NothingToClaim`.
     *
     *      Ordering: `accruedYield` is incremented BEFORE the transfer
     *      (checks-effects-interactions), and `nonReentrant` blocks re-entry
     *      through a non-standard yield token, so a partial claim can never be
     *      replayed to drain the same yield twice.
     *
     *      Reverts with `InvalidBondId`, `BondClosed` (a redeemed bond's yield
     *      was already paid by `redeem`), `NotBondHolder`, `NothingToClaim`
     *      when the accrued yield truncates to zero, or `InsufficientYieldPool`
     *      if the pool is unexpectedly short.
     * @param bondId 1-based id of the bond to collect from.
     */
    function claimYield(uint256 bondId) external nonReentrant {
        Bond storage bond = _requireBond(bondId);
        if (bond.closed) revert BondClosed(bondId);
        if (msg.sender != bond.holder) revert NotBondHolder(bondId, msg.sender);

        uint256 amount = pendingYield(bondId);
        if (amount == 0) revert NothingToClaim(bondId);

        uint256 available = yieldToken.balanceOf(address(this));
        if (available < amount) revert InsufficientYieldPool(amount, available);

        // Effects before interaction.
        bond.accruedYield += amount;

        yieldToken.safeTransfer(bond.holder, amount);

        emit YieldClaimed(bondId, bond.holder, amount);
    }

    /**
     * @notice Closes a matured bond, returning the principal CATT and the final
     *         accrued yield to its holder.
     * @dev Callable by ANYONE once the bond is mature, but the payout is
     *      always routed to `bond.holder`: allowing an arbitrary caller to
     *      choose the recipient would let a third party grief a holder by
     *      front-running the redemption. Permissionless triggering is safe
     *      precisely because the destination is fixed by the bond record and
     *      by nothing the caller controls.
     *
     *      REACHABLE EXACTLY ONCE. The bond is marked `closed` and its points
     *      are removed from `totalPoints` before either transfer, so a second
     *      redemption reverts with `BondClosed` and a late `claimYield` on the
     *      same bond reverts with `BondClosed` too — its final yield was paid
     *      here. Checks-effects-interactions plus `nonReentrant` means even a
     *      malicious yield token callback cannot re-enter into a second payout.
     *
     *      Maturity is a strict `block.timestamp >= maturesAt` comparison on
     *      `block.timestamp` only; no block number is read anywhere (PRD
     *      Rule 1).
     *
     *      Reverts with `InvalidBondId`, `BondClosed`, `BondNotMatured` while
     *      the term is still running, or `InsufficientYieldPool` if the yield
     *      leg cannot be covered.
     * @param bondId 1-based id of the bond to redeem.
     */
    function redeem(uint256 bondId) external nonReentrant {
        Bond storage bond = _requireBond(bondId);
        if (bond.closed) revert BondClosed(bondId);

        uint256 maturesAt = uint256(bond.maturesAt);
        if (block.timestamp < maturesAt) {
            revert BondNotMatured(bondId, maturesAt, block.timestamp);
        }

        uint256 finalYield = pendingYield(bondId);

        uint256 available = yieldToken.balanceOf(address(this));
        if (available < finalYield) revert InsufficientYieldPool(finalYield, available);

        uint256 principal = bond.principal;
        address holder = bond.holder;

        // Effects before interactions.
        bond.closed = true;
        bond.accruedYield += finalYield;
        totalPoints -= bond.points;

        principalToken.safeTransfer(holder, principal);
        yieldToken.safeTransfer(holder, finalYield);

        emit BondRedeemed(bondId, holder, principal, finalYield);
    }

    /**
     * @notice Loads a bond record, reverting if the id was never created.
     * @dev Existence is `holder != address(0)`: ids start at 1, so id 0 and any
     *      unissued id produce a zero-valued record. `address(0)` can never be
     *      a real holder because `buyBond` stores `msg.sender`, and the
     *      zero-address bond principal could not be paid out anyway.
     * @param bondId 1-based id of the bond.
     * @return bond Storage reference to the bond record.
     */
    function _requireBond(uint256 bondId) private view returns (Bond storage bond) {
        bond = _bonds[bondId];
        if (bond.holder == address(0)) revert InvalidBondId(bondId);
    }
}

contracts/CATT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title CATT Protocol Token ($CATT)
 * @notice Minimal, auditable ERC20 token for the CATT Protocol "Learn-to-Earn"
 *         economy (Polygon). The token is intentionally feature-free: there is
 *         no burn, no pause, no tax and no transfer hook. All supply control is
 *         funnelled through a single owner-gated, hard-cap-guarded `mint`.
 *
 * @dev Tokenomics (PRD Section 3.3):
 *      - Maximum supply is 100,000,000 CATT and is enforced at the contract
 *        level by `MAX_SUPPLY`. This cap is immutable and will NEVER be raised.
 *      - The decimals decision is immutable: 18 decimals is inherited from
 *        OpenZeppelin's `ERC20` implementation and is deliberately NOT
 *        overridden, so the value can never drift or be mis-configured.
 *      - Deployment parameters (owner address, RPC endpoints, private keys)
 *        come from the deployer's environment. No key material is stored in
 *        this source file (PRD Rule 2).
 *
 * @dev The fixed 18-decimal choice is documented on the inherited function
 *      rather than on a local override, because overriding `decimals()` would
 *      create a second, mutable source of truth for the same number.
 */
contract CATT is ERC20, Ownable {
    /// @notice Hard cap on the total number of CATT tokens that will ever exist.
    /// @dev 100,000,000 CATT expressed in the token's 18-decimal base unit.
    ///      This is a permanent cap: the value is a compile-time `constant`
    ///      with no setter, no upgrade path and no privileged bypass, so the
    ///      total supply can never exceed it.
    uint256 public constant MAX_SUPPLY = 100_000_000 * 10 ** 18;

    /// @notice Emitted on every successful mint, complementing the standard
    ///         ERC20 `Transfer` event emitted by the token implementation.
    /// @param to Recipient of the freshly minted tokens.
    /// @param amount Amount minted, in 18-decimal base units.
    /// @param newTotalSupply Total supply of CATT after the mint completed.
    event Minted(address indexed to, uint256 amount, uint256 newTotalSupply);

    /// @notice Thrown when a mint would push the total supply above `MAX_SUPPLY`.
    /// @param requestedSupply Resulting total supply that was requested.
    /// @param maxSupply The immutable hard cap (`MAX_SUPPLY`).
    error MintExceedsMaxSupply(uint256 requestedSupply, uint256 maxSupply);

    /**
     * @notice Deploys the CATT token.
     * @param initialOwner Address granted the exclusive right to mint CATT.
     * @dev Ownership can be transferred or renounced by the owner afterwards
     *      through OpenZeppelin's `Ownable`. Renouncing it permanently disables
     *      `mint` while leaving every already-minted token fully transferable.
     */
    constructor(address initialOwner) ERC20("CATT Protocol", "CATT") Ownable(initialOwner) {}

    /**
     * @notice Mints new CATT tokens to `to`.
     * @dev Emits both `Transfer` (via the ERC20 implementation) and `Minted`.
     *
     *      Reverts with `MintExceedsMaxSupply` if the mint would take the total
     *      supply beyond the immutable `MAX_SUPPLY` cap. Reverts with OpenZeppelin's
     *      `ERC20InvalidReceiver` if `to` is the zero address. A zero `amount`
     *      is not rejected here; the inherited ERC20 transfer path is the single
     *      source of truth for receiver and amount validity.
     *
     * @param to Recipient of the minted tokens. Must not be `address(0)`.
     * @param amount Amount of CATT to mint, in 18-decimal base units.
     */
    function mint(address to, uint256 amount) external onlyOwner {
        uint256 currentSupply = totalSupply();
        uint256 requestedSupply = currentSupply + amount;
        if (requestedSupply > MAX_SUPPLY) {
            revert MintExceedsMaxSupply(requestedSupply, MAX_SUPPLY);
        }

        _mint(to, amount);

        emit Minted(to, amount, totalSupply());
    }
}

contracts/MiningClaimer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "./CATT.sol";
import "./StakingManager.sol";

/**
 * @title CATT Protocol Mining Claimer
 * @notice The signature-verified settlement layer of the CATT "Learn-to-Earn"
 *         mining loop (PRD Section 3.2, "Signature Generator", and PRD Section
 *         6.2, "Mining Loop"). It closes the off-chain/on-chain loop: the
 *         backend Judge (PRD 3.2) runs the Anti-Cheat Engine, and when a user
 *         passes Proof-of-Attention it signs an EIP-712 statement. This contract
 *         verifies that signature, debits the stamina the mining session cost,
 *         and mints the signed $CATT reward to the user.
 *
 * @dev The loop this contract closes, verbatim from PRD 6.2:
 *      "User selects Mission -> Reads Article (triggers telemetry) -> Hits
 *      Focus Trap -> Passes Quiz -> Backend signs transaction -> User claims
 *      $CATT." Everything before "Backend signs" is off-chain and out of scope
 *      here; everything from "Backend signs" onwards is enforced on-chain.
 *
 * @dev CROSS-LANGUAGE CONTRACT (must byte-match the backend signer):
 *      - Domain name:    "CATT Protocol"  (passed to `EIP712`)
 *      - Domain version: "1"              (passed to `EIP712`)
 *      - chainId:         the live `block.chainid` (OpenZeppelin injects it)
 *      - verifyingContract: `address(this)` (OpenZeppelin injects it)
 *      - Type string, field order fixed and significant:
 *        `ClaimReward(address user,uint256 reward,uint256 staminaCost,uint256 nonce,uint256 deadline)`
 *        The `encodeData` struct order in `_claimStructHash` is `user`,
 *        `reward`, `staminaCost`, `nonce`, `deadline` — identical. The type
 *        hash literal and the encode order are two separate places where a
 *        mismatch would silently produce an unverifiable signature, so both are
 *        pinned here and the actual hash is built in exactly one private helper
 *        (`_claimStructHash`) that both `claimReward` and `hashClaim` use, so
 *        the two public entry points cannot drift apart.
 *
 * @dev Replay protection has two independent layers:
 *      - The `deadline` is inside the signed struct hash, so a signature is
 *        only usable until the timestamp it was issued against.
 *      - The `nonce` is inside the signed struct hash AND is recorded in the
 *        `usedNonces` mapping before any external call, so even a signature
 *        that stays valid for a long window can be spent exactly once.
 *
 * @dev Security posture (PRD Section 5, Rule 1):
 *      - `claimReward` is `nonReentrant`, and it follows
 *        checks-effects-interactions strictly: every check, then the
 *        `usedNonces` write, then the two external calls, then the event. The
 *        nonce is therefore consumed before any value leaves the protocol, so
 *        neither re-entry nor a downstream failure can mint twice.
 *      - All timing is derived strictly from `block.timestamp`; no block
 *        number is read anywhere in this contract.
 *      - There is no arithmetic in the settlement path: `reward` and
 *        `staminaCost` are consumed exactly as the signer committed to them,
 *        so no rounding, no fee and no share math exists to be mis-computed.
 *
 * @dev Deliberate non-goals, so that auditors do not look for them:
 *      - NO PERMIT2, NO META-TRANSACTIONS, NO EIP-2612 PERMIT. The claim is
 *        deliberately gasless from the *reward* point of view (the user does
 *        not need CATT to claim, and the backend pays the gas if it relays),
 *        but there is no meta-transaction implementation here at all.
 *      - NO OFF-CHAIN SIGNATURE ISSUANCE OR VERIFICATION. This contract only
 *        *checks* a signature; it never asks, receives or stores a Judge
 *        decision, an attestation, a telemetry report or an API response.
 *      - NO BACKEND OR MOBILE CODE. The Anti-Cheat Engine, the content
 *        randomizer and the app live in `/backend-server` and `/mobile-app`
 *        respectively (PRD Rule 3).
 *      - NO BATCH CLAIMS: one signature, one claim, one reward.
 *      - NO CLAIM FEE: the reward is minted in full to the user.
 *      - NO PAUSE: a signer that is compromised is revoked by rotation, not
 *        by a pause switch.
 *      - NO UPGRADEABILITY: not proxyable, not initializable, no admin
 *        storage writes beyond `signer`.
 *      - NO RE-SIGNING OR RELAYING OF ANOTHER USER'S CLAIM: `user` is baked
 *        into the signature, so a third party can submit a claim but can only
 *        ever trigger a payout to the address the backend signed for.
 *      - NO RECOVERY OF A BURNED NONCE (see `usedNonces`).
 *
 * @dev No private keys, API keys or deployment secrets appear in this source
 *      file. The backend signing key lives only in the Judge service's
 *      environment (PRD Rule 2); the on-chain contract only ever learns the
 *      signer's *address*.
 *
 * @dev DeploymentNotes — required deployment order, and the two roles this
 *      contract must hold:
 *
 *      This contract needs BOTH of the following roles, and they are granted
 *      by the deployment script in this exact order:
 *        (1) the CATT `Ownable` role — after this contract becomes the owner
 *            of `CATT` it is the SOLE account that can call `mint`, and
 *            therefore the only account from which mining rewards can ever be
 *            printed; and
 *        (2) the `StakingManager.claimer` role — only `claimer` may call
 *            `StakingManager.consumeStamina`, so it is the only account that
 *            can debit user stamina.
 *
 *      The steps, in order:
 *        (i)   MINT EVERY INITIAL ALLOCATION (team, treasury, liquidity,
 *              airdrop — anything that should exist at genesis) with the
 *              DEPLOYER still the owner of `CATT`. This ordering is not
 *              cosmetic: the moment `CATT` ownership is transferred to this
 *              contract, the deployer can no longer mint, and because this
 *              contract exposes no way to mint arbitrary allocations (its only
 *              mint path is a signed mining reward), any allocation minted
 *              after the transfer would be permanently unmintable.
 *        (ii)  `cattToken.transferOwnership(address(claimer))` — from the
 *              deployer, which must still be the owner per step (i).
 *        (iii) `stakingManager.setClaimer(address(claimer))` — from the
 *              `StakingManager` owner, granting the stamina-debit role.
 *        (iv)  Only after (ii) and (iii) does `claimReward` work end to end;
 *              before that point it reverts with `UnauthorizedClaimer` or
 *              `OwnableUnauthorizedAccount` respectively.
 *
 *      After (iv) this contract is the sole minter of $CATT and the only
 *      account that can debit stamina, which means the trust root of the
 *      whole economy is: (a) the `signer` key, which alone decides who gets
 *      minted what, and (b) the `Ownable` owner of THIS contract, which alone
 *      decides who that signer is.
 *
 *      Role separation, stated explicitly because it is easy to conflate:
 *      the backend Judge is the `signer` HERE (it produces EIP-712
 *      signatures); the backend Judge is *not* the `StakingManager.claimer`
 *      (that is this contract, so stamina can only ever be debited as part of
 *      a verified claim); and the backend Judge is *not* the `CATT` owner
 *      (that is this contract too). The Judge's key can therefore only ever
 *      cause `stamina -> reward` conversions at a rate the signer chose; it
 *      cannot move user principal, cannot mint without paying stamina, and
 *      cannot grant itself any other privilege.
 */
contract MiningClaimer is EIP712, Ownable, ReentrancyGuard {
    /// @notice EIP-712 struct hash for the mining claim, pinned as a literal so
    ///         the on-chain and off-chain encoders cannot disagree.
    /// @dev Exact pre-image:
    ///      `ClaimReward(address user,uint256 reward,uint256 staminaCost,uint256 nonce,uint256 deadline)`
    ///      Field order is part of the hash — reordering these fields changes
    ///      the value and every signature issued against the old order stops
    ///      verifying.
    bytes32 private constant CLAIM_REWARD_TYPEHASH =
        keccak256("ClaimReward(address user,uint256 reward,uint256 staminaCost,uint256 nonce,uint256 deadline)");

    /// @notice Immutable reference to the $CATT token minted as a mining reward.
    /// @dev `immutable` rather than a mutable storage slot: the reward is
    ///      denominated in this exact token, so allowing it to change would
    ///      silently reinterpret every signature the backend has ever issued.
    CATT public immutable cattToken;

    /// @notice Immutable reference to the StakingManager whose stamina this
    ///         contract debits as part of every claim.
    /// @dev `immutable` for the same reason as `cattToken`: stamina is
    ///      denominated in the ledger held by this exact manager, so a
    ///      swappable pointer would let rewards be paid against a foreign (or
    ///      empty) stamina ledger.
    StakingManager public immutable stakingManager;

    /// @notice Address whose EIP-712 signatures are accepted as claims.
    /// @dev This is the backend Judge (PRD 3.2): it runs the Anti-Cheat
    ///      Engine, and on a pass it signs the reward/stamina statement that
    ///      this contract settles. It is a pure *attester* role — it can mint
    ///      (indirectly, by signing) and it can burn stamina, but it holds no
    ///      token custody, no owner powers and no ability to move principal.
    ///      The owner rotates it with `setSigner`.
    address public signer;

    /// @notice Single-use markers for mined sessions, keyed by user then nonce.
    /// @dev Nonces are assigned by the backend and must be UNIQUE PER USER,
    ///      but they need not be sequential or ordered: uniqueness is the
    ///      entire security property, so a backend that issues them from a
    ///      counter, a database row id, or a random source is equally correct.
    ///      Strictly sequential per-user nonces (with a "next expected nonce"
    ///      check, which would also bound mapping growth) are a possible future
    ///      hardening item, deliberately deferred for the MVP because they
    ///      would let a single griefed future nonce block every later claim.
    ///
    ///      A USED NONCE IS BURNED FOREVER. There is no expiry, no reuse, no
    ///      refund and no admin override: `usedNonces[user][nonce]` is written
    ///      to `true` and can never return to `false`. This is intentional and
    ///      is the desired anti-replay semantics — a nonce that has paid out
    ///      once must never pay out again for the lifetime of the deployment.
    ///      The practical consequence is that a nonce griefed by a third party
    ///      (by submitting the user's own valid claim early) is unusable for
    ///      all time; the user simply asks the backend for a fresh nonce.
    mapping(address => mapping(uint256 => bool)) public usedNonces;

    /// @notice Emitted for every settled mining claim.
    /// @param user Account the reward was minted to; also the account whose
    ///        stamina was debited.
    /// @param reward Amount of CATT minted, in 18-decimal base units.
    /// @param staminaCost Stamina points debited from `user`.
    /// @param nonce Backend-issued nonce consumed by this claim. Permanently
    ///        burned once this event is observed.
    /// @param signer Address whose signature authorized the claim; equal to
    ///        the `signer` role at execution time.
    event RewardClaimed(address indexed user, uint256 reward, uint256 staminaCost, uint256 nonce, address indexed signer);

    /// @notice Emitted when the authorized signer is changed.
    /// @param previousSigner The signer that was active before the change.
    /// @param newSigner The signer that is active after the change.
    event SignerUpdated(address indexed previousSigner, address indexed newSigner);

    /// @notice Thrown when a token, staking manager or signer address is `address(0)`.
    /// @dev The zero address is never a valid actor here: a zero token or
    ///      manager would make the deployment permanently unusable, and a zero
    ///      signer would brick every claim (or worse, be an address whose key
    ///      nobody controls, so no signature could ever verify).
    error ZeroAddress();

    /// @notice Thrown when a well-formed signature recovers to an address that
    ///         is not the current `signer`.
    /// @dev Only covers the "signed by the wrong key" case. A malformed
    ///      `signature` does NOT reach this error: `ECDSA.recover` itself
    ///      reverts with OpenZeppelin's `ECDSAInvalidSignature` (or
    ///      `ECDSAInvalidSignatureLength`) before any comparison happens, and
    ///      that revert is deliberately NOT caught or wrapped. See
    ///      `claimReward` for why.
    /// @param expectedSigner The `signer` the contract currently trusts.
    /// @param recoveredSigner The address the submitted signature recovered to.
    error ClaimSignatureInvalid(address expectedSigner, address recoveredSigner);

    /// @notice Thrown when a claim arrives after its signed deadline.
    /// @param deadline The signed expiry timestamp that was passed.
    /// @param currentTime `block.timestamp` at execution, i.e. how late it is.
    error ClaimExpired(uint256 deadline, uint256 currentTime);

    /// @notice Thrown when a nonce has already been spent for this user.
    /// @param user The user whose nonce space was hit.
    /// @param nonce The already-consumed nonce.
    error ClaimAlreadyUsed(address user, uint256 nonce);

    /// @notice Thrown when ECDSA recovery fails outright, i.e. yields the
    ///         zero address or is otherwise unusable.
    /// @dev Kept as a distinct, explicit signal for a dead signature rather
    ///      than folding it into `ClaimSignatureInvalid`, so an indexer can
    ///      tell "wrong key" apart from "no key at all". Malformed signature
    ///      BYTES are a separate case again: OpenZeppelin's `ECDSA.recover`
    ///      rejects them itself and reverts with its own `ECDSAInvalidSignature`
    ///      before this contract can observe anything.
    error InvalidSignature();

    /**
     * @notice Deploys the mining claimer against a CATT token and a StakingManager.
     * @dev The signer is supplied at construction rather than left unset, so
     *      the contract is usable the moment it is deployed. All three
     *      addresses must be non-zero or the deployment reverts.
     *
     *      Emits `SignerUpdated(address(0), initialSigner_)` so an indexer
     *      sees a genesis value for the role instead of having to infer it
     *      from the constructor arguments, matching the pattern used by
     *      `StakingManager`'s `claimer`.
     * @param cattToken_ Address of the `CATT` ERC20 token to mint rewards from.
     * @param stakingManager_ Address of the `StakingManager` to debit stamina from.
     * @param initialSigner_ Address of the backend Judge (PRD 3.2) whose
     *        signatures are accepted.
     */
    constructor(address cattToken_, address stakingManager_, address initialSigner_)
        EIP712("CATT Protocol", "1")
        Ownable(msg.sender)
    {
        if (cattToken_ == address(0)) revert ZeroAddress();
        if (stakingManager_ == address(0)) revert ZeroAddress();
        if (initialSigner_ == address(0)) revert ZeroAddress();

        cattToken = CATT(cattToken_);
        stakingManager = StakingManager(stakingManager_);
        signer = initialSigner_;

        emit SignerUpdated(address(0), initialSigner_);
    }

    /**
     * @notice EIP-712 digest the backend, the frontend and the tests must all
     *         be signing for the given claim parameters.
     * @dev Exposed deliberately, as the single source of truth for the exact
     *      bytes a signature must cover. The backend should build its digest
     *      independently and the test suite can assert equality against this
     *      value; if the two ever disagree, the mismatch is a bug in the
     *      encoders, not something a user should discover on-chain.
     *
     *      Reads `block.chainid` and `address(this)` live, so the digest
     *      returned here is the digest that will be checked at execution time
     *      on the current chain. On any other chain, or against any other
     *      `MiningClaimer` deployment, the domain separator differs and a
     *      signature produced for this digest will not recover to the signer.
     * @param user Account the reward is for and whose stamina is charged.
     * @param reward CATT amount to mint, in 18-decimal base units.
     * @param staminaCost Stamina points to debit from `user`.
     * @param nonce Backend-issued, per-user-unique claim nonce.
     * @param deadline Unix timestamp after which the claim is no longer valid.
     * @return digest The final EIP-712 digest, i.e. `keccak256(0x1901 || domainSeparator || structHash)`.
     */
    function hashClaim(address user, uint256 reward, uint256 staminaCost, uint256 nonce, uint256 deadline)
        external
        view
        returns (bytes32 digest)
    {
        digest = _hashTypedDataV4(_claimStructHash(user, reward, staminaCost, nonce, deadline));
    }

    /**
     * @notice Whether the given nonce has already been spent by `user`.
     * @dev Thin, self-documenting alias over the public `usedNonces` mapping,
     *      provided so the frontend can ask the question in the same
     *      vocabulary the claim flow uses. Read-only: it cannot be used to
     *      consume a nonce.
     * @param user Account whose nonce space is being queried.
     * @param nonce The nonce to test.
     * @return used True if the nonce was already consumed; false if it is still available.
     */
    function isNonceUsed(address user, uint256 nonce) external view returns (bool used) {
        used = usedNonces[user][nonce];
    }

    /**
     * @notice Settles one signed mining claim: debits `staminaCost` stamina from
     *         `user` and mints `reward` CATT to `user`.
     *
     * @dev `user` IS INTENTIONALLY INDEPENDENT OF `msg.sender`. The user
     *      submits (or a relayer submits on their behalf, which is what makes
     *      the PRD 3.2 "Gasless transaction" flow possible), but the reward
     *      ALWAYS goes to `user` and the stamina is ALWAYS debited from
     *      `user`. This is safe precisely because `user` is part of the signed
     *      struct hash: a third party can trigger a claim, but can only ever
     *      trigger a payout to the address the backend actually signed for, and
     *      can never redirect it. There is no "claim on behalf of" variant
     *      that would break this, and none is provided.
     *
     * @dev CHECK ORDER, which is deliberate:
     *      0. `user != address(0)`. Checked first because every later step
     *         dereferences `user`; a zero user would burn stamina against the
     *         zero address, which is unrecoverable.
     *      1. SIGNATURE. The EIP-712 digest is rebuilt from the call arguments
     *         and recovered, then compared against `signer`. This is the
     *         authorization gate, so it is evaluated before any state read or
     *         write: an unauthorized caller must not be able to burn a nonce,
     *         probe `usedNonces`, or make the contract do work on its behalf.
     *         Note the two distinct failure shapes, deliberately NOT merged:
     *         a MALFORMED signature (bad length, invalid `s`/`v`) makes
     *         `ECDSA.recover` revert with OpenZeppelin's own
     *         `ECDSAInvalidSignature`, which is not caught or wrapped here so
     *         the revert reason stays the library's; a well-formed signature
     *         from the WRONG KEY recovers successfully and surfaces as this
     *         contract's `ClaimSignatureInvalid(signer, recovered)`.
     *      2. DEADLINE, using a strict `>`: a claim is valid while
     *         `block.timestamp <= deadline`, so the backend controls the exact
     *         expiry instant, down to and including the deadline second.
     *      3. NONCE, checked after the signature because an unused, validly
     *         signed nonce is a normal user action while a replayed one is an
     *         attack, and the attacker cannot even reach this check without a
     *         valid signature. Checked before any write so a double-spend is
     *         rejected rather than self-healing.
     *
     *      EFFECTS BEFORE INTERACTIONS: `usedNonces[user][nonce]` is set to
     *      `true` BEFORE `consumeStamina` and `mint` are called. So a
     *      re-entrant call (or any external observer mid-call) can never see
     *      the nonce as available again, and the mint is only ever reached
     *      through an already-burned nonce. If `consumeStamina` or `mint`
     *      reverts — insufficient stamina, the hard cap reached, the owner role
     *      not yet granted — the ENTIRE transaction reverts, including this
     *      write, so the nonce is released again. That is correct and intended:
     *      a nonce is only permanently burned when a reward was actually paid
     *      for it, and a failed claim leaves the user free to retry.
     *      `nonReentrant` is a second, independent barrier on top of this.
     *
     *      There is no partial settlement: `consumeStamina` and `mint` are
     *      both required to succeed, so a reward is never minted without the
     *      stamina having been consumed and stamina is never consumed without
     *      the reward being minted.
     *
     *      This contract must hold the CATT `Ownable` role (it is the sole
     *      minter after deployment) AND the `StakingManager.claimer` role. See
     *      the DeploymentNotes block above for the required ordering, and
     *      note in particular that initial allocations MUST be minted by the
     *      deployer BEFORE CATT ownership is transferred here, since after the
     *      transfer the deployer can no longer mint and this contract has no
     *      other mint path.
     *
     * @param user Account the reward is minted to and whose stamina is
     *        debited. Intentionally independent of `msg.sender`.
     * @param reward Amount of CATT to mint, in 18-decimal base units.
     * @param staminaCost Stamina points to debit from `user`.
     * @param nonce Backend-issued nonce, unique per `user`, consumed forever
     *        by a successful call.
     * @param deadline Unix timestamp after which this claim is rejected; the
     *        claim is valid while `block.timestamp <= deadline`.
     * @param signature The backend's EIP-712 signature over
     *        `hashClaim(user, reward, staminaCost, nonce, deadline)`.
     */
    function claimReward(
        address user,
        uint256 reward,
        uint256 staminaCost,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) external nonReentrant {
        // 0. A zero user would burn stamina to an unrecoverable address.
        if (user == address(0)) revert ZeroAddress();

        // 1. Authorization: rebuild the digest from the call arguments and
        //    recover. Malformed bytes revert inside `ECDSA.recover` with
        //    OpenZeppelin's `ECDSAInvalidSignature`; a well-formed signature
        //    from the wrong key is reported as `ClaimSignatureInvalid`.
        bytes32 structHash = _claimStructHash(user, reward, staminaCost, nonce, deadline);
        address recovered = ECDSA.recover(_hashTypedDataV4(structHash), signature);
        if (recovered == address(0)) revert InvalidSignature();
        if (recovered != signer) revert ClaimSignatureInvalid(signer, recovered);

        // 2. Expiry. Strict `>`, so the claim is valid through `deadline`
        //    itself and expires on the following second.
        if (block.timestamp > deadline) revert ClaimExpired(deadline, block.timestamp);

        // 3. Replay: the nonce must not have been spent by this user before.
        if (usedNonces[user][nonce]) revert ClaimAlreadyUsed(user, nonce);

        // 4. EFFECTS FIRST. The nonce is burned before any external call, so
        //    it cannot be consumed twice even if a downstream call re-enters
        //    or the downstream call fails. A revert below unwinds this write
        //    together with the rest of the transaction, releasing the nonce,
        //    which is correct because no reward was paid for it.
        usedNonces[user][nonce] = true;

        // 5. INTERACTIONS. Both must succeed or the whole claim reverts; there
        //    is no path that pays stamina without minting or vice versa.
        stakingManager.consumeStamina(user, staminaCost);
        cattToken.mint(user, reward);

        emit RewardClaimed(user, reward, staminaCost, nonce, signer);
    }

    /**
     * @notice Points `newSigner` as the address whose claim signatures are
     *         accepted, replacing the previous one atomically.
     * @dev ROTATION TAKES EFFECT IMMEDIATELY AND WITHOUT ANY GRACE PERIOD.
     *      A signature produced by the previous signer stops verifying the very
     *      next block: there is no pending-signature buffer, no overlap window
     *      and no "old key still good for N seconds" allowance, because the
     *      signature check compares against the `signer` value read in the same
     *      transaction, and that value is the new one from the block after this
     *      call is mined. In-flight claims signed by the outgoing key simply
     *      revert with `ClaimSignatureInvalid`. This is the intended
     *      emergency-revocation behaviour for a compromised backend Judge: the
     *      fastest possible kill switch beats a graceful handover, and the
     *      cost of a reverting claim is only the user's gas for a retry with a
     *      freshly signed nonce.
     *
     *      The trade-off is stated rather than hidden: rotating the signer
     *      invalidates every unclaimed signature from the old key, so the
     *      backend should sign short-lived deadlines (or hold a small queue of
     *      unsigned claims) so a planned rotation does not strand users
     *      mid-loop. Revoking an attacker is worth far more than preserving a
     *      handful of in-flight claims.
     *
     *      Reverts with `ZeroAddress` on the zero address so the role can never
     *      be left unset, which would brick every future claim and permanently
     *      freeze mining with no way to fix it.
     * @param newSigner Address to trust. Must not be `address(0)`.
     */
    function setSigner(address newSigner) external onlyOwner {
        if (newSigner == address(0)) revert ZeroAddress();

        address previous = signer;
        signer = newSigner;

        emit SignerUpdated(previous, newSigner);
    }

    /**
     * @notice Builds the EIP-712 struct hash for a mining claim.
     * @dev THE single place where the struct hash is constructed. Both
     *      `claimReward` (which signs) and `hashClaim` (which publishes the
     *      expected digest) route through this helper, so the bytes a user is
     *      asked to submit a signature for and the bytes the contract actually
     *      verifies are structurally incapable of drifting apart.
     *
     *      The field order MUST match the `ClaimReward(...)` type string
     *      encoded in `CLAIM_REWARD_TYPEHASH` exactly: `user`, `reward`,
     *      `staminaCost`, `nonce`, `deadline`.
     * @param user Account the reward is for and whose stamina is charged.
     * @param reward CATT amount to mint, in 18-decimal base units.
     * @param staminaCost Stamina points to debit from `user`.
     * @param nonce Backend-issued, per-user-unique claim nonce.
     * @param deadline Unix timestamp after which the claim is no longer valid.
     * @return structHash The EIP-712 struct hash for these parameters.
     */
    function _claimStructHash(address user, uint256 reward, uint256 staminaCost, uint256 nonce, uint256 deadline)
        private
        pure
        returns (bytes32 structHash)
    {
        structHash = keccak256(
            abi.encode(
                CLAIM_REWARD_TYPEHASH,
                user,
                reward,
                staminaCost,
                nonce,
                deadline
            )
        );
    }
}

contracts/mocks/MockUSDT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

/**
 * @title MockUSDT — TEST-ONLY USDT-style stablecoin double
 * @notice A deliberately minimal, deliberately UNSAFE stand-in for a
 *         6-decimal USDT, used only to prove that `BondManager` makes no
 *         assumption that its yield token has 18 decimals.
 *
 * @dev ####################################################################
 * @dev ### TEST-ONLY. MUST NEVER BE DEPLOYED TO A PUBLIC NETWORK.        ###
 * @dev ####################################################################
 *      This contract exists solely to live under `contracts/mocks/` and back
 *      the BondManager unit tests. It is imported by NOTHING in
 *      `contracts/` outside this folder, it is permissionless (anyone may
 *      mint), it has no access control, no pause and no supply cap, and it
 *      therefore has none of the guarantees a real stablecoin provides.
 *      Deploying it on Polygon — or anywhere else with real value — would let
 *      anyone print the token the bond pool pays out in.
 *
 *      The 6-decimal `decimals()` override is the whole point: it is what
 *      proves the yield accounting is decimals-agnostic, so the same contract
 *      works unchanged against a 6-decimal USDT and a 18-decimal DAI.
 */
contract MockUSDT is ERC20 {
    /// @notice Deploys the double named and symbolised as USDT.
    constructor() ERC20("Mock USDT", "USDT") {}

    /// @notice Mints `amount` base units to `to`.
    /// @dev Intentionally permissionless and uncapped, for the reasons given
    ///      in the contract header: this is a test double, not a token.
    /// @param to Recipient of the freshly minted tokens.
    /// @param amount Amount minted, in 6-decimal base units.
    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }

    /// @notice Number of decimals of this token, fixed at 6 like real USDT.
    /// @dev Overrides the 18-decimal default inherited from OpenZeppelin's
    ///      `ERC20` on purpose, so tests exercise a non-18-decimal yield token.
    /// @return decimals Always 6.
    function decimals() public pure override returns (uint8) {
        return 6;
    }
}

contracts/StakingManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title CATT Protocol Staking & Stamina Manager
 * @notice The on-chain "Learn-to-Earn" engine of CATT Protocol ($CATT): the
 *         tiered staking requirement that unlocks Stamina (PRD Section 3.3)
 *         together with the anti-dump "Drip Unstaking" release path.
 *
 * @dev Economy (PRD Section 3.3, "Stamina System" / "Tiered Staking" / "Drip
 *      Unstaking"):
 *      - Stamina is the daily spend resource used to mine $CATT. It is minted
 *        in-contract purely as a staking reward: every successful stake pays
 *        `STAMINA_PER_STAKE` points. It is unitless and has no monetary value.
 *      - The stake requirement is a *percentage of the caller's current CATT
 *        balance*, and it escalates with the caller's level: level 0 costs
 *        `BASE_STAKE_PERCENT` (10%), and every further level adds
 *        `LEVEL_STEP_PERCENT` (5%), saturating at `MAX_STAKE_PERCENT` (90%).
 *        A higher level therefore makes the NEXT stake more expensive, which is
 *        the intended sink for CATT.
 *      - Unstaking is deliberately "drip" only: a request releases exactly
 *        `UNSTAKE_BPS` (10.00%) of the staked balance and starts an
 *        `UNSTAKE_COOLDOWN` (84 hours / 3.5 days) window before another request
 *        is accepted. A full exit is therefore a multi-day drip by
 *        construction, which is the PRD's explicit anti-dump design.
 *
 * @dev Security posture (PRD Section 5, Rule 1):
 *      - Every state-changing function is `nonReentrant`, and all balance
 *        updates are written before the external token call, so a non-standard
 *        or malicious CATT implementation cannot re-enter and drain the vault.
 *      - All timing logic is derived strictly from `block.timestamp`. No block
 *        number is read anywhere in this contract, so miners/validators cannot
 *        decouple the cooldown from wall-clock time.
 *      - `SafeERC20` is used for every transfer, so USDT-style tokens that do
 *        not return a boolean on `transfer` are still handled correctly.
 *
 * @dev Deliberate non-goals, so that auditors do not look for them:
 *      no bond/vesting yield logic (that lives in a separate contract), no burn,
 *      no fee-on-transfer accounting, no emergency pause, no admin slashing or
 *      clawback, no off-chain signature verification, and no upgradeability.
 *      The `cattToken` address is `immutable`; the contract holds no admin
 *      ability to move user principal other than the 10% drip release.
 *
 * @dev No private keys, API keys or deployment secrets appear in this source
 *      file; those are supplied by the deployer's environment (PRD Rule 2).
 */
contract StakingManager is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    /// @notice Percentage of the caller's CATT balance required at level 0
    ///         (10%). PRD 3.3: "Level 1: 10%" — the contract counts levels
    ///         from zero, so `stakeLevel == 0` is the PRD's "Level 1".
    uint256 public constant BASE_STAKE_PERCENT = 10;

    /// @notice Percentage points added to the requirement for every level
    ///         gained. PRD 3.3: "Level 2: 15%, +5% per level".
    uint256 public constant LEVEL_STEP_PERCENT = 5;

    /// @notice Hard ceiling on the stake requirement, reached at level 16.
    /// @dev A cap is required so the requirement can never reach 100% (which
    ///      would be unpayable) and can never be used to demand a user's whole
    ///      balance; a 10% buffer is always retained, which also leaves the
    ///      user liquid CATT to sell or bond.
    uint256 public constant MAX_STAKE_PERCENT = 90;

    /// @notice Stamina paid out per successful stake, in stamina points.
    /// @dev Fixed, not level-scaled: stamina is a *rate* resource for daily
    ///      mining, and the escalating cost of the next stake is the intended
    ///      economic pressure. Keeping it flat also keeps the reward
    ///      predictable for the frontend.
    uint256 public constant STAMINA_PER_STAKE = 50;

    /// @notice Delay between two accepted unstake requests: 84 hours (3.5 days).
    /// @dev PRD 3.3: "an 84-hour (3.5 days) cooldown between requests".
    uint256 public constant UNSTAKE_COOLDOWN = 84 hours;

    /// @notice Basis-point share of the staked balance released per request:
    ///         1000 bps = 10.00%. PRD 3.3: "Max unstake is 10% of staked
    ///         amount".
    uint256 public constant UNSTAKE_BPS = 1000;

    /// @notice Basis-point denominator used by every bps computation (100.00%).
    uint256 public constant BPS_DENOMINATOR = 10_000;

    /// @notice Immutable reference to the CATT ERC20 token locked and released
    ///         by this contract.
    /// @dev `immutable` rather than a mutable storage slot: the staked
    ///      principal is denominated in this token, so allowing it to change
    ///      would silently reinterpret every user's balance.
    IERC20 public immutable cattToken;

    /// @notice CATT currently locked by `user` in this contract, in
    ///         18-decimal base units.
    /// @dev Only ever moves in two ways: up via `stakeForStamina`, and down by
    ///      exactly the 10% drip released via `requestUnstake`. There is no
    ///      admin path that can reduce it, so principal is safe from seizure.
    mapping(address => uint256) public stakedAmount;

    /// @notice Staking level of `user`, starting at 0.
    /// @dev Increments by one on every successful `stakeForStamina` and NEVER
    ///      decreases — not even when the user unstakes. The level is a
    ///      monotone "how much CATT has been committed here" counter that
    ///      drives `requiredPercent`; letting it decay would let a user reset
    ///      the escalation by cycling stake -> unstake -> stake.
    mapping(address => uint256) public stakeLevel;

    /// @notice Stamina balance of `user`, in unitless stamina points.
    /// @dev Credited by `stakeForStamina` and debited only by the authorized
    ///      `claimer` via `consumeStamina`. The owner cannot debit it directly.
    mapping(address => uint256) public stamina;

    /// @notice Timestamp of `user`'s most recent accepted unstake request.
    /// @dev 0 means the user has never requested an unstake, in which case no
    ///      cooldown is in force and the next request is served immediately.
    ///      Because a real chain timestamp is never 0, the zero value is an
    ///      unambiguous "never" marker rather than an edge case.
    mapping(address => uint256) public lastUnstakeRequest;

    /// @notice Account authorized to debit stamina on behalf of users.
    /// @dev In the reference deployment this is the backend "Judge" (PRD 3.2)
    ///      which verifies Proof-of-Attention and calls `consumeStamina` when
    ///      a mining session is spent. It is deliberately NOT the owner: role
    ///      separation means a compromised owner cannot drain user stamina, and
    ///      a compromised claimer can only ever destroy stamina (never mint it
    ///      or move principal). The owner administers the role through
    ///      `setClaimer` and is never implicitly authorized.
    address public claimer;

    /// @notice Emitted on every successful stake.
    /// @param user Account that staked.
    /// @param amount Amount pulled from the user, in 18-decimal base units.
    /// @param newStakedAmount Total locked for the user after the stake.
    /// @param newStakeLevel The user's level after the stake (level + 1).
    event Staked(address indexed user, uint256 amount, uint256 newStakedAmount, uint256 newStakeLevel);

    /// @notice Emitted on every successful unstake request.
    /// @param user Account that unstaked.
    /// @param amount Amount transferred out, in 18-decimal base units.
    /// @param newStakedAmount Total still locked for the user after the release.
    /// @param nextUnstakeAvailableAt Timestamp from which the next request is
    ///        accepted for this user.
    event Unstaked(address indexed user, uint256 amount, uint256 newStakedAmount, uint256 nextUnstakeAvailableAt);

    /// @notice Emitted when stamina is credited to a user.
    /// @param user Account that received the stamina.
    /// @param amountGranted Stamina points added in this action.
    /// @param newStamina The user's total stamina after the credit.
    event StaminaGranted(address indexed user, uint256 amountGranted, uint256 newStamina);

    /// @notice Emitted when stamina is debited from a user.
    /// @param user Account that was debited.
    /// @param amountConsumed Stamina points removed in this action.
    /// @param newStamina The user's remaining stamina after the debit.
    event StaminaConsumed(address indexed user, uint256 amountConsumed, uint256 newStamina);

    /// @notice Emitted when the authorized stamina claimer is changed.
    /// @param previousClaimer The claimer that was active before the change.
    /// @param newClaimer The claimer that is active after the change.
    event ClaimerUpdated(address indexed previousClaimer, address indexed newClaimer);

    /// @notice Thrown when a token, claimer or beneficiary address is `address(0)`.
    /// @dev The zero address is never a valid actor: accepting it would either
    ///      brick the role permanently or credit stamina to an unrecoverable
    ///      burn address.
    error ZeroAddress();

    /// @notice Thrown when a supplied amount is zero.
    /// @dev A zero amount is always a caller mistake or a no-op, and letting it
    ///      through would consume a transaction and emit misleading events.
    error ZeroAmount();

    /// @notice Thrown by `requestUnstake` when the caller has nothing staked.
    error NotStaker();

    /// @notice Thrown when the 10% drip truncates to zero for a dust stake.
    /// @param staked The caller's total staked balance, in base units.
    /// @param amount The drip amount after integer division, i.e. always 0.
    error UnstakeAmountTooSmall(uint256 staked, uint256 amount);

    /// @notice Thrown when a stake is below the caller's level-scaled minimum.
    /// @param required Minimum stake, in 18-decimal base units.
    /// @param provided Amount the caller tried to stake.
    error InsufficientStakeAmount(uint256 required, uint256 provided);

    /// @notice Thrown when an unstake request arrives inside the 84h window.
    /// @param secondsRemaining Exact seconds left until the request is allowed.
    error UnstakeCooldownActive(uint256 secondsRemaining);

    /// @notice Thrown when the claimer tries to debit more stamina than exists.
    /// @dev `account` is the offending address itself, so the ABI argument is
    ///      the same 32-byte word an `address` always encodes to, but the type
    ///      can no longer be confused with a level or an amount.
    /// @param account The account that was debited against.
    /// @param requested Stamina points the claimer tried to consume.
    /// @param available Stamina points the account actually held.
    error StaminaInsufficient(address account, uint256 requested, uint256 available);

    /// @notice Thrown when a non-claimer tries to consume someone else's stamina.
    /// @param caller The address that attempted the call.
    error UnauthorizedClaimer(address caller);

    /**
     * @notice Deploys the staking manager against a CATT token address.
     * @dev `claimer` is initialised to the deployer so the protocol is usable
     *      the moment it is deployed: if it were left unset, every
     *      `consumeStamina` call would revert with `UnauthorizedClaimer` until
     *      a separate owner transaction granted the role, leaving freshly
     *      deployed users unable to mine. The owner can (and in production
     *      should) immediately reassign it to the backend Judge service with
     *      `setClaimer`, after which the deployer address no longer holds any
     *      privilege over stamina.
     * @param cattToken_ Address of the CATT ERC20 token to be staked.
     */
    constructor(address cattToken_) Ownable(msg.sender) {
        if (cattToken_ == address(0)) revert ZeroAddress();

        cattToken = IERC20(cattToken_);
        claimer = msg.sender;

        emit ClaimerUpdated(address(0), msg.sender);
    }

    /**
     * @notice Percentage of `user`'s CATT balance that must be staked for the
     *         next stake, in whole percent.
     * @dev `min(BASE_STAKE_PERCENT + stakeLevel[user] * LEVEL_STEP_PERCENT,
     *      MAX_STAKE_PERCENT)`. `stakeLevel` is deliberately left unbounded: the
     *      clamp is applied to the RESULT of the multiplication, so an
     *      arbitrarily large level can only ever push the percentage up to the
     *      90% ceiling and can never wrap around, reduce the requirement, or
     *      make the computation revert. See `MAX_STAKE_PERCENT` for why 90%
     *      and not 100%.
     * @param user Account whose requirement is being queried.
     * @return percent Required percentage of the user's balance, capped at
     *         `MAX_STAKE_PERCENT`.
     */
    function requiredPercent(address user) public view returns (uint256 percent) {
        uint256 escalated = BASE_STAKE_PERCENT + (stakeLevel[user] * LEVEL_STEP_PERCENT);
        percent = escalated < MAX_STAKE_PERCENT ? escalated : MAX_STAKE_PERCENT;
    }

    /**
     * @notice Minimum amount of CATT that `user` must stake right now to earn
     *         stamina, in 18-decimal base units.
     * @dev `balanceOf(user) * requiredPercent(user) / 100`. The balance is the
     *      caller's SPENDABLE balance, i.e. it excludes CATT already locked in
     *      this contract, which is what makes the requirement escalate as
     *      principal is committed. Integer division floors the result, so a
     *      very small balance can round down to a dust minimum; that is
     *      harmless because it can only make the requirement trivially cheap,
     *      never unpayable.
     * @param user Account whose requirement is being queried.
     * @return amount Minimum stake, in 18-decimal base units.
     */
    function requiredStakeFor(address user) public view returns (uint256 amount) {
        amount = (cattToken.balanceOf(user) * requiredPercent(user)) / 100;
    }

    /**
     * @notice Stamina balance of `user`, in unitless stamina points.
     * @dev Thin, self-documenting wrapper over the public `stamina` mapping.
     *      It exists so the frontend/backend can read the balance through one
     *      obviously-named entry point alongside `requiredStakeFor` and
     *      `nextUnstakeAvailableAt`, and so the storage layout can later gain
     *      derived fields without changing the external read API.
     * @param user Account whose stamina is being queried.
     * @return amount Stamina points currently available to spend.
     */
    function staminaOf(address user) external view returns (uint256 amount) {
        amount = stamina[user];
    }

    /**
     * @notice Timestamp at which `user` may request another unstake.
     * @dev Returns 0 when the user has never made a request, meaning "no
     *      cooldown has ever been armed" rather than "available since the
     *      epoch". Consumers should pair this with
     *      `unstakeCooldownRemaining`, which is 0 in both the never-requested
     *      and cooldown-elapsed cases.
     * @param user Account whose next available timestamp is being queried.
     * @return nextAvailable `lastUnstakeRequest[user] + UNSTAKE_COOLDOWN`, or
     *         0 if the user has never requested an unstake.
     */
    function nextUnstakeAvailableAt(address user) public view returns (uint256 nextAvailable) {
        uint256 last = lastUnstakeRequest[user];
        if (last == 0) return 0;
        nextAvailable = last + UNSTAKE_COOLDOWN;
    }

    /**
     * @notice Seconds `user` must still wait before the next unstake request.
     * @dev 0 when the user has never requested an unstake AND 0 when the
     *      cooldown has fully elapsed, so a non-zero value is always an
     *      unambiguous "you are locked out, here is exactly how long".
     *      The subtraction is guarded so the result can never wrap around if
     *      the chain's timestamp were ever to move backwards.
     * @param user Account whose remaining cooldown is being queried.
     * @return remaining Seconds left, or 0 if no cooldown is in force.
     */
    function unstakeCooldownRemaining(address user) public view returns (uint256 remaining) {
        uint256 last = lastUnstakeRequest[user];
        if (last == 0) return 0;
        uint256 nextAvailable = last + UNSTAKE_COOLDOWN;
        if (block.timestamp >= nextAvailable) return 0;
        remaining = nextAvailable - block.timestamp;
    }

    /**
     * @notice Locks `amount` CATT and credits `STAMINA_PER_STAKE` stamina to the
     *         caller.
     *
     * @dev Requirement semantics, stated precisely because they are the heart
     *      of the tiered-staking design:
     *      - `requiredStakeFor(msg.sender)` is evaluated against the caller's
     *        balance BEFORE this stake lands, because the required amount is
     *        computed (and checked) before the transfer is pulled. Since the
     *        CATT being staked is not part of the caller's spendable balance
     *        anyway, a user who holds exactly 10% of their supply in CATT
     *        spends 10% of their spendable balance to stake, and that same
     *        10% is *not* added to the basis for the following stake.
     *      - OVER-STAKING IS ALLOWED: the check is `amount >= required`, not
     *        `amount == required`. A user may lock any amount from the
     *        requirement up to their whole balance, and may repeatedly add to
     *        an existing position.
     *      - EVERY successful stake raises `stakeLevel` by exactly one, and the
     *        level never decreases. So each 50 stamina points purchased makes
     *        the NEXT stake strictly more expensive (+5 percentage points,
     *        saturating at 90%), which is the intended CATT sink.
     *
     *      Ordering: the external `safeTransferFrom` is performed BEFORE the
     *      bookkeeping writes. This is a deliberate choice, not an oversight.
     *      Pulling the tokens first means a transfer that is not honoured (a
     *      rebasing or block-list-aware token, a token whose `transferFrom`
     *      charges a fee, or any future non-standard behaviour) reverts the
     *      whole transaction, so stamina and level can never be granted for
     *      tokens this contract never received. The classic
     *      checks-effects-interactions argument for writing state first relies
     *      on the invariant being observable by a re-entrant caller, which does
     *      not apply here: the `nonReentrant` modifier already blocks every
     *      re-entrant path into this contract, so the residual risk that the
     *      inversion would otherwise introduce is nil, while the pull-first
     *      ordering additionally keeps the accounting honest against
     *      exotic token behaviour.
     *
     *      Reverts with `ZeroAmount` for a zero amount, and with
     *      `InsufficientStakeAmount` when the stake is below the level-scaled
     *      minimum. Reverts with the standard ERC20 allowance/balance errors if
     *      the caller has not approved this contract.
     *
     * @param amount Amount of CATT to lock, in 18-decimal base units. Must be
     *        greater than or equal to `requiredStakeFor(msg.sender)`.
     */
    function stakeForStamina(uint256 amount) external nonReentrant {
        if (amount == 0) revert ZeroAmount();

        uint256 required = requiredStakeFor(msg.sender);
        if (amount < required) revert InsufficientStakeAmount(required, amount);

        // Interaction first, effects after: see the ordering rationale above.
        cattToken.safeTransferFrom(msg.sender, address(this), amount);

        stakedAmount[msg.sender] += amount;
        stakeLevel[msg.sender] += 1;
        uint256 granted = STAMINA_PER_STAKE;
        stamina[msg.sender] += granted;

        emit Staked(msg.sender, amount, stakedAmount[msg.sender], stakeLevel[msg.sender]);
        emit StaminaGranted(msg.sender, granted, stamina[msg.sender]);
    }

    /**
     * @notice Releases the 10% drip of the caller's staked CATT and arms the
     *         84-hour cooldown.
     *
     * @dev The call is parameterless on purpose: the amount is derived from the
     *      caller's own staked balance, so a caller can never choose to release
     *      more than the 10% cap, and can never release to anyone but
     *      themselves. The exit path is therefore exactly PRD 6.4: request ->
     *      receive 10% -> timer resets for 84 hours.
     *
     *      Cooldown semantics, precisely:
     *      - The FIRST request a user ever makes is served immediately and is
     *        what ARMS the clock: `lastUnstakeRequest` is 0 until that moment,
     *        so no cooldown is ever charged twice for the same window.
     *      - After the first request, further requests revert with
     *        `UnstakeCooldownActive` until
     *        `lastUnstakeRequest + UNSTAKE_COOLDOWN` has passed. Each subsequent
     *        successful request RE-ARMS the clock from its own timestamp, so
     *        repeated drip-outs are spaced at least 84 hours apart and a
     *        determined seller is limited to 10% of the position every 3.5
     *        days. This is the PRD's intended anti-dump design, not an oversight
     *        that a first-timer could exploit for a free exit.
     *      - The comparison uses `block.timestamp` only, never a block number
     *        (PRD Rule 1). Two requests cannot be served for the same user
     *        within one 84h window, so a same-block double call is impossible.
     *
     *      Truncation: `amount = staked * UNSTAKE_BPS / BPS_DENOMINATOR` is an
     *      integer division, so a position below 10 base units (e.g. 9 wei)
     *      yields a drip of 0. Rather than silently no-op, that case reverts
     *      with `UnstakeAmountTooSmall`, because a zero-value drip could
     *      neither move tokens nor make progress towards unwinding the
     *      position. Such a dust position is only reachable by a user who
     *      deliberately stakes dust, and can never block a normal position:
     *      the revert is per-caller and state is untouched.
     *
     *      Ordering: state is written BEFORE the transfer
     *      (checks-effects-interactions), and `nonReentrant` additionally
     *      blocks re-entry through a non-standard token callback.
     *
     *      Reverts with `NotStaker` if nothing is staked, with
     *      `UnstakeAmountTooSmall` for a dust position, and with
     *      `UnstakeCooldownActive` while the window is still open.
     */
    function requestUnstake() external nonReentrant {
        uint256 staked = stakedAmount[msg.sender];
        if (staked == 0) revert NotStaker();

        uint256 amount = (staked * UNSTAKE_BPS) / BPS_DENOMINATOR;
        if (amount == 0) revert UnstakeAmountTooSmall(staked, amount);

        uint256 last = lastUnstakeRequest[msg.sender];
        if (last != 0) {
            uint256 nextAvailable = last + UNSTAKE_COOLDOWN;
            if (block.timestamp < nextAvailable) {
                revert UnstakeCooldownActive(nextAvailable - block.timestamp);
            }
        }

        uint256 newStakedAmount = staked - amount;
        stakedAmount[msg.sender] = newStakedAmount;
        uint256 requestTimestamp = block.timestamp;
        lastUnstakeRequest[msg.sender] = requestTimestamp;

        cattToken.safeTransfer(msg.sender, amount);

        emit Unstaked(msg.sender, amount, newStakedAmount, requestTimestamp + UNSTAKE_COOLDOWN);
    }

    /**
     * @notice Debits `amount` stamina from `account`. Callable only by the
     *         authorized `claimer`.
     * @dev `account` is DELIBERATELY allowed to differ from `msg.sender`.
     *      Per PRD 3.2 the backend Judge validates Proof-of-Attention, and a
     *      mined session is charged to the wallet that earned it; the frontend
     *      relays the call so the user does not pay gas, which is why the
     *      signature-authorized backend, not the end user, is `msg.sender`.
     *      This is safe because the claimer is a single trusted role that can
     *      only ever DESTROY stamina (never mint it, never touch principal) and
     *      can be rotated by the owner through `setClaimer`.
     *
     *      Note that the owner is NOT implicitly authorized: role separation
     *      means a compromised owner cannot drain user stamina, and no
     *      accidental owner call can silently burn a session. The owner must
     *      explicitly `setClaimer` to grant itself the role.
     *
     *      Reverts with `UnauthorizedClaimer` for any other caller,
     *      `ZeroAddress` if `account` is the zero address, `ZeroAmount` if
     *      `amount` is zero, and `StaminaInsufficient` if the balance is too
     *      low. State is written before any event, and this function performs
     *      no external calls at all.
     *
     * @param account User whose stamina is consumed. Must not be
     *        `address(0)` and need not be the caller.
     * @param amount Stamina points to burn, in stamina points. Must be > 0 and
     *        at most `stamina[account]`.
     */
    function consumeStamina(address account, uint256 amount) external nonReentrant {
        if (msg.sender != claimer) revert UnauthorizedClaimer(msg.sender);
        if (account == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();

        uint256 available = stamina[account];
        if (available < amount) revert StaminaInsufficient(account, amount, available);

        uint256 newStamina = available - amount;
        stamina[account] = newStamina;

        emit StaminaConsumed(account, amount, newStamina);
    }

    /**
     * @notice Points `newClaimer` as the account allowed to call
     *         `consumeStamina`, replacing the previous one atomically.
     * @dev Reverts with `ZeroAddress` on the zero address so the role can never
     *      be left unset, which would brick every stamina consumption in the
     *      protocol. The change takes effect immediately, so any in-flight
     *      trusted call from the previous claimer reverts with
     *      `UnauthorizedClaimer` from the next block onwards — the intended
     *      emergency-revocation path.
     * @param newClaimer Address to authorize. Must not be `address(0)`.
     */
    function setClaimer(address newClaimer) external onlyOwner {
        if (newClaimer == address(0)) revert ZeroAddress();

        address previous = claimer;
        claimer = newClaimer;

        emit ClaimerUpdated(previous, newClaimer);
    }
}

contracts/TeamVesting.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title CATT Protocol Team & Treasury Vesting
 * @notice Custody and linear release schedule for the two locked allocations of
 *         the CATT Protocol supply described in the PRD: Team (15%) and
 *         Treasury (20%). The contract holds CATT tokens and streams them to two
 *         named beneficiaries over a 1-year cliff followed by 3 years of linear
 *         vesting (4 years total from deployment).
 *
 * @dev Design notes:
 *      - Exactly two beneficiaries are registered, in the constructor. There is
 *        no registry, no array and no way to add or remove beneficiaries, which
 *        makes the allocation set fully known at deployment time.
 *      - CATT is an ERC20 token, so this contract needs no `receive()` /
 *        `fallback()`. The deployer funds the contract by transferring CATT
 *        into it with `IERC20(cattToken).transfer(address(vesting), amount)`
 *        (or `safeTransfer`) after deployment.
 *      - All release decisions are computed from `block.timestamp` on-chain.
 *        There is no pause, no admin clawback and no off-chain signature path,
 *        so the contract cannot be used to confiscate vested tokens.
 *      - No private keys, API keys or deployment secrets appear in this source
 *        file; those are supplied by the deployer's environment (PRD Rule 2).
 */
contract TeamVesting is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    /// @notice One-year cliff: nothing is releasable before it elapses.
    uint256 public constant CLIFF_DURATION = 365 days;

    /// @notice Total vesting schedule length measured from `startTime`
    ///         (1-year cliff + 3 years of linear vesting).
    uint256 public constant VESTING_DURATION = 4 * 365 days;

    /// @notice Immutable reference to the CATT token held and released here.
    IERC20 public immutable cattToken;

    /// @notice Per-beneficiary vesting schedule and release bookkeeping.
    /// @param total Total CATT allocated to the beneficiary, in 18-decimal units.
    /// @param released Amount already transferred out to the beneficiary.
    /// @param startTime Timestamp at which the schedule began.
    /// @param cliffDuration Seconds of cliff after `startTime`.
    /// @param duration Seconds from `startTime` until the schedule is fully vested.
    struct Allocation {
        uint256 total;
        uint256 released;
        uint256 startTime;
        uint256 cliffDuration;
        uint256 duration;
    }

    /// @notice Vesting allocations keyed by beneficiary address.
    /// @dev A beneficiary absent from this mapping has a zero-valued
    ///      `Allocation`, which all views treat as "nothing allocated".
    mapping(address => Allocation) public allocations;

    /// @notice Thrown when the constructor or a future setter receives a zero address.
    error ZeroAddress();

    /// @notice Thrown when an allocation amount is zero.
    error ZeroAmount();

    /// @notice Thrown when both beneficiaries would be the same address.
    error DuplicateBeneficiary();

    /// @notice Thrown when the vesting schedule would be degenerate, i.e. when
    ///         there is no time window in which tokens vest linearly.
    error InvalidVestingSchedule();

    /// @notice Thrown when `claim()` is called by a beneficiary with nothing releasable.
    error NothingToClaim();

    /// @notice Thrown when the contract's CATT balance is lower than the
    ///         amount it is about to release (i.e. it was under-funded).
    error InsufficientVestedBalance();

    /**
     * @notice Deploys the vesting contract and registers both allocations.
     *
     * @dev Intended deployment values for the amounts (passed in by the
     *      deployer rather than hardcoded, so the contract stays agnostic of
     *      the token's supply configuration):
     *        - `teamAmount`      = 15_000_000 * 10 ** 18  (15% of the 100,000,000 CATT max supply)
     *        - `treasuryAmount`  = 20_000_000 * 10 ** 18  (20% of the 100,000,000 CATT max supply)
     *      After deployment the deployer must transfer exactly this much CATT
     *      into this contract; until then `claim()` reverts with
     *      `InsufficientVestedBalance`.
     *
     *      Both allocations start at `block.timestamp` with a 365-day cliff and
     *      a 4-year total schedule, so nothing is releasable during year 1 and
     *      the allocation streams linearly over the following 3 years, reaching
     *      100% exactly 4 years after deployment.
     *
     * @param cattToken_ Address of the CATT ERC20 token being vested.
     * @param teamBeneficiary Address entitled to the team allocation.
     * @param treasuryBeneficiary Address entitled to the treasury allocation.
     * @param teamAmount Team allocation, in 18-decimal base units. Must be > 0.
     * @param treasuryAmount Treasury allocation, in 18-decimal base units. Must be > 0.
     */
    constructor(
        address cattToken_,
        address teamBeneficiary,
        address treasuryBeneficiary,
        uint256 teamAmount,
        uint256 treasuryAmount
    ) Ownable(msg.sender) {
        if (cattToken_ == address(0)) revert ZeroAddress();
        if (teamBeneficiary == address(0)) revert ZeroAddress();
        if (treasuryBeneficiary == address(0)) revert ZeroAddress();
        if (teamAmount == 0 || treasuryAmount == 0) revert ZeroAmount();
        if (teamBeneficiary == treasuryBeneficiary) revert DuplicateBeneficiary();
        if (VESTING_DURATION <= CLIFF_DURATION) revert InvalidVestingSchedule();

        cattToken = IERC20(cattToken_);

        uint256 startTime = block.timestamp;
        allocations[teamBeneficiary] = Allocation({
            total: teamAmount,
            released: 0,
            startTime: startTime,
            cliffDuration: CLIFF_DURATION,
            duration: VESTING_DURATION
        });
        allocations[treasuryBeneficiary] = Allocation({
            total: treasuryAmount,
            released: 0,
            startTime: startTime,
            cliffDuration: CLIFF_DURATION,
            duration: VESTING_DURATION
        });
    }

    /**
     * @notice Amount of CATT that has vested for `beneficiary` at the current block.
     * @dev Vesting schedule, with `S = startTime`, `C = cliffDuration`, `D = duration`:
     *        - `now <= S + C`           -> 0 (nothing vests during the cliff)
     *        - `S + C < now < S + D`   -> `total * (now - (S + C)) / (D - C)`
     *        - `now >= S + D`          -> `total` (fully vested)
     *      `D` is the total schedule length from `S`, so the linear window is
     *      `D - C` (3 years with the 365-day cliff and 4-year duration), and the
     *      accumulator is bounded by that same window, which keeps the result
     *      within `[0, total]`. Integer division floors the result, so a
     *      beneficiary can never round up past `total`.
     * @param beneficiary Address whose allocation is being queried.
     * @return amount Cumulative vested amount, in 18-decimal base units.
     */
    function vestedAmount(address beneficiary) public view returns (uint256 amount) {
        Allocation memory allocation = allocations[beneficiary];
        if (allocation.total == 0) return 0;

        uint256 startTime = allocation.startTime;
        uint256 cliffDuration = allocation.cliffDuration;
        uint256 duration = allocation.duration;
        uint256 currentTime = block.timestamp;

        if (currentTime <= startTime + cliffDuration) return 0;

        uint256 vestingWindow = duration - cliffDuration;
        // Defensive guards. The constructor makes a zero or inverted window
        // impossible, but a division by zero would brick claims, so saturate to
        // the full amount instead of reverting.
        if (vestingWindow == 0) return allocation.total;
        if (currentTime >= startTime + duration) return allocation.total;

        // `elapsed` is bounded by `vestingWindow` here, so the linear result is
        // always <= total. The clamp below is belt-and-braces only.
        uint256 elapsed = currentTime - (startTime + cliffDuration);
        amount = (allocation.total * elapsed) / vestingWindow;
        if (amount > allocation.total) amount = allocation.total;
    }

    /**
     * @notice Amount of CATT `beneficiary` can still withdraw right now.
     * @param beneficiary Address whose allocation is being queried.
     * @return amount `vestedAmount(beneficiary)` minus the amount already released.
     */
    function releasable(address beneficiary) public view returns (uint256 amount) {
        Allocation memory allocation = allocations[beneficiary];
        if (allocation.total == 0) return 0;

        uint256 vested = vestedAmount(beneficiary);
        if (vested <= allocation.released) return 0;

        amount = vested - allocation.released;
    }

    /**
     * @notice Claims everything currently releasable by the caller.
     * @dev Funds always go to `msg.sender`; there is no way for one beneficiary
     *      to claim on behalf of another, so tokens can never be diverted.
     *      `released` is incremented before the external token call (checks
     *      effects / interactions) and `nonReentrant` blocks re-entrancy from a
     *      non-standard CATT implementation.
     *
     *      Reverts with `NothingToClaim` when the caller has no registered
     *      allocation or nothing has vested yet, and with
     *      `InsufficientVestedBalance` when this contract holds less CATT than
     *      the releasable amount (i.e. it was not fully funded by the deployer).
     */
    function claim() external nonReentrant {
        address beneficiary = msg.sender;
        uint256 amount = releasable(beneficiary);
        if (amount == 0) revert NothingToClaim();

        Allocation storage allocation = allocations[beneficiary];
        allocation.released += amount;

        if (cattToken.balanceOf(address(this)) < amount) revert InsufficientVestedBalance();

        cattToken.safeTransfer(beneficiary, amount);
    }
}

